// ============================================
// VALIDATION INPUT - Content Analyzer
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Required context fields ---
const userId = body.user_id || ctx.user_id;
const guildId = body.guild_id || ctx.guild_id;
const userRequest = body.user_request || ctx.user_request;

if (!userId) {
  errors.push('user_id requis');
}
if (!guildId) {
  errors.push('guild_id requis');
}
if (!userRequest) {
  errors.push('user_request requis');
}

// --- Specific webhook parameters ---
const imageUrl = body.image_url || ctx.image_url || null;
const imageData = body.image_data || ctx.image_data || null;
const domain = body.domain || ctx.domain || 'general';
const availableTools = body.available_tools || ctx.available_tools || [];

// Must have either image_url or image_data
if (!imageUrl && !imageData) {
  errors.push('image_url ou image_data (base64) requis');
}

// available_tools should be an array
if (!Array.isArray(availableTools) || availableTools.length === 0) {
  errors.push('available_tools (array non vide) requis');
}

// --- API Keys passed from MCP Server ---
const openaiApiKey = body.openai_api_key || ctx.openai_api_key || body.plugin_context?.api_keys?.openai || '';

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

// Determine image source
let imageSource = 'url';
let imageContent = imageUrl;
if (imageData && !imageUrl) {
  imageSource = 'base64';
  imageContent = imageData;
}

return {
  valid: true,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  image_url: imageUrl,
  image_data: imageData,
  image_source: imageSource,
  domain: domain,
  available_tools: availableTools,
  openaiApiKey: openaiApiKey,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

