// ============================================
// PARSE LLM RESPONSE - Content Analyzer
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

// --- Context fields for traceability ---
const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

const statusCode = input.statusCode || 200;

// Initialize trace with llm_response format
const _trace = {
  llm_response: null,
  service_response: null,
  provider: 'openai',
  model: 'gpt-4o',
  tokens: { input: 0, output: 0 },
  latency_ms: 0,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

// Handle API error
if (statusCode >= 400 || input.error) {
  const errorMsg = input.body?.error?.message || input.error?.message || 'Vision LLM API error';
  _trace.llm_response = `Error: ${errorMsg}`;
  _trace.service_response = input.body || input;
  _trace.latency_ms = Date.now() - startTime;

  return {
    json: {
      success: false,
      error: {
        code: 'LLM_ERROR',
        message: errorMsg,
        http_status: statusCode
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
}

// Extract response
const body = input.body || input;
const content = body.choices?.[0]?.message?.content || '';
const usage = body.usage || {};

// Populate trace with LLM response
_trace.llm_response = content;
_trace.service_response = body;
_trace.tokens = {
  input: usage.prompt_tokens || 0,
  output: usage.completion_tokens || 0
};

// Parse JSON from response
let parsed;
try {
  // Handle markdown code blocks
  let jsonStr = content;
  const codeBlockMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (codeBlockMatch) {
    jsonStr = codeBlockMatch[1].trim();
  } else {
    const rawMatch = content.match(/\{[\s\S]*\}/);
    if (rawMatch) jsonStr = rawMatch[0];
  }

  parsed = JSON.parse(jsonStr);
} catch (e) {
  _trace.latency_ms = Date.now() - startTime;

  return {
    json: {
      success: false,
      error: {
        code: 'PARSE_ERROR',
        message: 'Failed to parse LLM response: ' + e.message,
        http_status: 500
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
}

// Validate parsed response structure
const analysis = parsed.analysis || {};
const pipeline = parsed.pipeline || [];
const confidence = typeof parsed.confidence === 'number' ? Math.min(1, Math.max(0, parsed.confidence)) : 0.5;

// Validate pipeline tools against available_tools
const availableTools = prevData.available_tools || [];
const invalidTools = pipeline.filter(step => !availableTools.includes(step.tool)).map(step => step.tool);

// Normalize analysis fields
const normalizedAnalysis = {
  content_type: analysis.content_type || 'unknown',
  has_text: Boolean(analysis.has_text),
  text_type: analysis.text_type || 'none',
  detected_items: Array.isArray(analysis.detected_items) ? analysis.detected_items : [],
  language: analysis.language || null
};

// Normalize pipeline
const normalizedPipeline = pipeline.map((step, idx) => ({
  step: step.step || idx + 1,
  tool: step.tool,
  input: step.input || null,
  on_fail: ['abort', 'skip', 'fallback'].includes(step.on_fail) ? step.on_fail : 'abort',
  reason: step.reason || null
}));

_trace.latency_ms = Date.now() - startTime;

return {
  json: {
    success: true,
    data: {
      analysis: normalizedAnalysis,
      pipeline: normalizedPipeline,
      confidence: confidence
    },
    meta: {
      domain: prevData.domain,
      available_tools: prevData.available_tools,
      image_source: prevData.image_source,
      invalid_tools: invalidTools.length > 0 ? invalidTools : undefined,
      processing_time_ms: Date.now() - startTime
    },
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest,
    _trace: _trace
  }
};
